import { test, expect } from '@playwright/test';

test.describe('Mark All Notifications as Read', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the notifications page
    await page.goto('/notifications');
    // Wait for notifications to load
    await page.waitForLoadState('networkidle');
  });

  test('should display mark all as read button when notifications exist', async ({ page }) => {
    // Verify that the mark all as read button is visible
    const markAllButton = page.getByRole('button', { name: /mark all as read/i });
    await expect(markAllButton).toBeVisible();
  });

  test('should mark all unread notifications as read with one click', async ({ page }) => {
    // Get all unread notification items before clicking
    const unreadNotifications = page.locator('[data-testid="notification-item"][data-unread="true"]');
    const unreadCountBefore = await unreadNotifications.count();

    // Verify there are unread notifications
    expect(unreadCountBefore).toBeGreaterThan(0);

    // Click the mark all as read button
    const markAllButton = page.getByRole('button', { name: /mark all as read/i });
    await markAllButton.click();

    // Wait for the notifications to update
    await page.waitForLoadState('networkidle');

    // Verify all notifications are now marked as read
    const unreadNotificationsAfter = page.locator('[data-testid="notification-item"][data-unread="true"]');
    const unreadCountAfter = await unreadNotificationsAfter.count();
    expect(unreadCountAfter).toBe(0);
  });

  test('should disable mark all as read button when all notifications are already read', async ({ page }) => {
    // First, mark all as read
    const markAllButton = page.getByRole('button', { name: /mark all as read/i });
    await markAllButton.click();
    await page.waitForLoadState('networkidle');

    // Verify the button is disabled or not visible
    await expect(markAllButton).toBeDisabled();
  });

  test('should show success message after marking all notifications as read', async ({ page }) => {
    // Click the mark all as read button
    const markAllButton = page.getByRole('button', { name: /mark all as read/i });
    await markAllButton.click();

    // Wait for success message to appear
    const successMessage = page.getByText(/all notifications marked as read/i);
    await expect(successMessage).toBeVisible();

    // Verify the message disappears after a few seconds
    await page.waitForTimeout(3000);
    await expect(successMessage).not.toBeVisible();
  });

  test('should update notification badge count after marking all as read', async ({ page }) => {
    // Get the notification badge element
    const notificationBadge = page.locator('[data-testid="notification-badge"]');

    // Get the initial count
    const initialBadgeText = await notificationBadge.textContent();
    const initialCount = parseInt(initialBadgeText || '0');

    expect(initialCount).toBeGreaterThan(0);

    // Click mark all as read
    const markAllButton = page.getByRole('button', { name: /mark all as read/i });
    await markAllButton.click();
    await page.waitForLoadState('networkidle');

    // Verify badge count is now 0
    const finalBadgeText = await notificationBadge.textContent();
    const finalCount = parseInt(finalBadgeText || '0');
    expect(finalCount).toBe(0);
  });

  test('should maintain notification list after marking all as read', async ({ page }) => {
    // Get the count of all notifications
    const allNotifications = page.locator('[data-testid="notification-item"]');
    const totalNotificationsBefore = await allNotifications.count();

    // Click mark all as read
    const markAllButton = page.getByRole('button', { name: /mark all as read/i });
    await markAllButton.click();
    await page.waitForLoadState('networkidle');

    // Verify the notification list still contains the same number of items
    const totalNotificationsAfter = await allNotifications.count();
    expect(totalNotificationsAfter).toBe(totalNotificationsBefore);

    // Verify all notifications have the read state
    const readNotifications = page.locator('[data-testid="notification-item"][data-unread="false"]');
    const readCount = await readNotifications.count();
    expect(readCount).toBe(totalNotificationsAfter);
  });
});
